# owner: platform
import unittest

from hourglass.models import Span
from hourglass.rounding import round_labels


class RoundLabelsTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        span = Span(9 * 60 + 7, 17 * 60 + 13)
        self.assertEqual(
            round_labels([span], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_half_step_rounds_up(self):
        span = Span(8, 67)
        self.assertEqual(
            round_labels([span], 15),
            ["00:15-01:00 (0h 45m)"]
        )

    def test_one_label_per_span(self):
        spans = [Span(0, 60), Span(120, 180)]
        self.assertEqual(len(round_labels(spans, 30)), 2)

    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)


if __name__ == "__main__":
    unittest.main()
